import 'package:flutter/material.dart';
import 'new_invoice_screen.dart';
import '../../core/database/database_helper.dart';
import '../../core/services/pdf_service.dart';

class InvoicesScreen extends StatefulWidget{const InvoicesScreen({super.key});@override State<InvoicesScreen> createState()=>_InvoicesState();}
class _InvoicesState extends State<InvoicesScreen>{@override Widget build(BuildContext c)=>FutureBuilder(future:DatabaseHelper.instance.all('invoices'),builder:(c,s){final rows=s.data??[];return ListView(padding:const EdgeInsets.all(12),children:[Align(alignment:Alignment.centerLeft,child:FilledButton.icon(onPressed:()async{await Navigator.push(c,MaterialPageRoute(builder:(_)=>const NewInvoiceScreen()));setState((){});},icon:const Icon(Icons.add),label:const Text('فاتورة جديدة'))),const SizedBox(height:10),if(rows.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(28),child:Center(child:Text('لا توجد فواتير بعد')))) else SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:const[DataColumn(label:Text('رقم الفاتورة')),DataColumn(label:Text('اسم العميل')),DataColumn(label:Text('التاريخ')),DataColumn(label:Text('الإجمالي')),DataColumn(label:Text('إجراءات'))],rows:rows.map((r)=>DataRow(cells:[DataCell(Text(r['number'])),DataCell(Text(r['customer_name']??'')),DataCell(Text((r['created_at']??'').toString().split('T').first)),DataCell(Text('${r['total']} ر.س')),DataCell(Row(children:[IconButton(tooltip:'طباعة ومشاركة',onPressed:()async{await PdfService.printInvoice(number:r['number'],customer:r['customer_name']??'',subtotal:r['subtotal'],tax:r['tax'],total:r['total']);},icon:const Icon(Icons.print,color:Color(0xFF0D47A1))),IconButton(onPressed:()async{await DatabaseHelper.instance.delete('invoices',r['id']);setState((){});},icon:const Icon(Icons.delete,color:Colors.red))]))])).toList())]);});}
}
